      window: 'віконце', key: 'клавіша', lamp: 'лампочка',
      ringRow: 'кільце', coreRow: 'дроти', ringAria: 'Кільце на C: у віконці E, дроти стоять на C',
      ringCap: 'Кільце встановлене на C: у віконці (червона рамка) видно E, а дроти стоять на C, бо E − C = C (A = 0, B = 1, C = 2 …, по колу).',
